import subprocess, os, sys
B='/workspace/executable'
def r(args, env=None, cwd=None, stdin=b'', timeout=60, envi=False, label=''):
    if envi:
        cmd=['env','-i']+["%s=%s"%(k,v) for k,v in (env or {}).items()]+[B]+args
        e=None
    else:
        cmd=[B]+args
        e=dict(os.environ)
        if env: 
            for k,v in env.items():
                if v is None: e.pop(k,None)
                else: e[k]=v
    try:
        p=subprocess.run(cmd,input=stdin,stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd=cwd,env=e,timeout=timeout)
        rc,o,er,to=p.returncode,p.stdout,p.stderr,False
    except subprocess.TimeoutExpired as ex:
        rc,o,er,to=None,ex.stdout or b'',ex.stderr or b'',True
    print('=== %s'%label); print('CMD: '+' '.join(repr(c) for c in cmd))
    if not envi and env: print('ENVDELTA: %r'%(env,))
    if cwd: print('CWD: %r'%cwd)
    print('EXIT: %r  TIMEOUT: %r'%(rc,to))
    print('OUT: %r'%o); print('ERR: %r'%er); print()
    return rc,o,er
